<?php
declare(strict_types=1);
function skynoc_manual_order(PDO $db,int $orderId,string $key,int $userId): array {
 $key=trim($key);if($orderId<1||$key==='')throw new RuntimeException('Order and key required.');
 $db->beginTransaction();try{$q=$db->prepare('SELECT o.*,p.name package_name,p.billing_period FROM orders o JOIN packages p ON p.id=o.package_id WHERE o.id=? FOR UPDATE');$q->execute([$orderId]);$o=$q->fetch();if(!$o||!in_array($o['status'],['pending','processing'],true))throw new RuntimeException('Order is not pending.');$q=$db->prepare('SELECT id FROM licenses WHERE license_key=? LIMIT 1 FOR UPDATE');$q->execute([$key]);if($q->fetchColumn())throw new RuntimeException('Key already exists.');$expires=null;if($o['billing_period']==='monthly')$expires=(new DateTimeImmutable('now'))->modify('+1 month')->format('Y-m-d H:i:s');elseif($o['billing_period']==='annual')$expires=(new DateTimeImmutable('now'))->modify('+1 year')->format('Y-m-d H:i:s');$db->prepare('INSERT INTO licenses(license_key,domain,reseller_id,status,purchase_date,expires_at,package_id) VALUES(?,?,?,"active",CURDATE(),?,?)')->execute([$key,$o['domain'],$o['reseller_id'],$expires,$o['package_id']]);$lid=(int)$db->lastInsertId();$db->prepare('UPDATE orders SET license_id=?,status="completed",notes=?,completed_at=NOW(),updated_at=NOW() WHERE id=?')->execute([$lid,'Manual fulfillment',$orderId]);$db->prepare('INSERT INTO license_history(license_id,user_id,action,old_domain,new_domain,notes) VALUES(?,?,?,?,?,?)')->execute([$lid,$userId,'manual_provision',null,$o['domain'],'Order #'.$orderId]);$db->commit();platform_invoice_for_order($orderId);notify_reseller((int)$o['reseller_id'],'order','Order completed','Order #'.$orderId.' completed. Key: '.$key);if(function_exists('discord_notify'))discord_notify('ORDER COMPLETED','Order #'.$orderId.' | '.$o['package_name'].' | '.$o['domain'],'success');if(function_exists('telegram_notify'))telegram_notify('ORDER COMPLETED | #'.$orderId.' | '.$key);return ['id'=>$lid,'key'=>$key];}catch(Throwable $e){if($db->inTransaction())$db->rollBack();throw $e;}}
